impl Solution {
    pub fn stone_game_v(stone_value: Vec<i32>) -> i32 {
        let n = stone_value.len();
        if n == 0 {
            return 0;
        }
        // prefix sums for O(1) range sum queries
        let mut pref = vec![0i64; n + 1];
        for i in 0..n {
            pref[i + 1] = pref[i] + stone_value[i] as i64;
        }
        let range_sum = |i: usize, j: usize| -> i64 { pref[j + 1] - pref[i] };

        // dp[i][j] = maximum score for subarray i..j inclusive
        let mut dp = vec![vec![0i64; n]; n];

        for len in 2..=n {
            for i in 0..=n - len {
                let j = i + len - 1;
                let mut best = 0i64;
                for k in i..j {
                    let left = range_sum(i, k);
                    let right = range_sum(k + 1, j);
                    let candidate = if left < right {
                        left + dp[i][k]
                    } else if left > right {
                        right + dp[k + 1][j]
                    } else {
                        let left_score = left + dp[i][k];
                        let right_score = right + dp[k + 1][j];
                        if left_score > right_score {
                            left_score
                        } else {
                            right_score
                        }
                    };
                    if candidate > best {
                        best = candidate;
                    }
                }
                dp[i][j] = best;
            }
        }
        dp[0][n - 1] as i32
    }
}

